import { supabase } from "@/integrations/supabase/client";

/**
 * Shared types and helpers for the resource library.
 *
 * The generated Supabase types are regenerated by Lovable and won't know about `resources` until it
 * does that, so queries use the same `as never` / `as any` escape hatch ReferenceQuestions.tsx and the
 * old ResourceBank already use. These interfaces are what the app actually relies on.
 */

export type ResourceKind =
  | "book"
  | "past_paper"
  | "mark_scheme"
  | "notes"
  | "handout"
  | "problem_set"
  | "other";

export type ResourceVisibility = "private" | "global";

export interface Resource {
  id: string;
  title: string;
  author: string | null;
  kind: ResourceKind;
  subject: string | null;
  level: string | null;
  description: string | null;
  visibility: ResourceVisibility;
  owner_id: string | null;
  storage_bucket: string;
  storage_path: string;
  content_type: string;
  byte_size: number | null;
  page_count: number | null;
  license_note: string | null;
  license_status: "unreviewed" | "cleared" | "restricted";
  text_status: "pending" | "indexed" | "no_text_layer" | "failed";
  chunk_count: number;
  created_by: string | null;
  created_at: string;
}

export interface ResourceProgress {
  resource_id: string;
  last_page: number;
  furthest_page: number;
  updated_at: string;
}

export const KIND_LABEL: Record<ResourceKind, string> = {
  book: "Book",
  past_paper: "Past paper",
  mark_scheme: "Mark scheme",
  notes: "Notes",
  handout: "Handout",
  problem_set: "Problem set",
  other: "Document",
};

export const KIND_OPTIONS = Object.entries(KIND_LABEL) as [ResourceKind, string][];

/**
 * Every bucket in this project is PRIVATE — including spec-documents, whose migration claims otherwise
 * (the CREATE was an ON CONFLICT DO NOTHING against a bucket that already existed). getPublicUrl returns
 * a URL-shaped string for a private object rather than failing, so it yields a link that 404s only once
 * a user clicks it. That is exactly the bug the old Resource Bank page shipped with. Always sign.
 */
export async function getResourceUrl(resource: Pick<Resource, "storage_bucket" | "storage_path">, expiresIn = 3600) {
  const { data, error } = await supabase.storage
    .from(resource.storage_bucket)
    .createSignedUrl(resource.storage_path, expiresIn);
  if (error) throw error;
  return data.signedUrl;
}

export function formatBytes(bytes: number | null): string {
  if (!bytes) return "";
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

/** Percent read, for the progress bar on a library card. Null when the page count is unknown. */
export function readPercent(progress: ResourceProgress | undefined, pageCount: number | null): number | null {
  if (!progress || !pageCount || pageCount < 1) return null;
  return Math.min(100, Math.round((progress.furthest_page / pageCount) * 100));
}
